-- Precompute a CFrame per joint per keyframe, and which joints each animation uses.
local function toCFrame(p)
	if not p then
		return CFrame.new()
	end
	return CFrame.new(p.x or 0, p.y or 0, p.z or 0)
		* CFrame.Angles(math.rad(p.rx or 0), math.rad(p.ry or 0), math.rad(p.rz or 0))
end

for _, anim in pairs(Data) do
	anim.UsedJoints = {}
	anim.Markers = {}
	for _, kf in ipairs(anim.Keyframes) do
		for jointName in pairs(kf.Poses) do
			anim.UsedJoints[jointName] = true
		end
		if kf.Marker then
			table.insert(anim.Markers, { Name = kf.Marker, Time = kf.Time })
		end
	end
	for _, kf in ipairs(anim.Keyframes) do
		kf.CFrames = {}
		for jointName in pairs(anim.UsedJoints) do
			kf.CFrames[jointName] = toCFrame(kf.Poses[jointName])
		end
	end
end

-- Pose of one joint in one keyframe (used by the builder to make KeyframeSequences).
function GuardianAnimations.GetKeyframePose(animName, keyframeIndex, jointName)
	return Data[animName].Keyframes[keyframeIndex].CFrames[jointName] or CFrame.new()
end

local function sample(anim, t, jointName)
	local kfs = anim.Keyframes
	local last = kfs[#kfs]
	if t >= last.Time then
		return last.CFrames[jointName]
	end
	for i = 1, #kfs - 1 do
		local a, b = kfs[i], kfs[i + 1]
		if t <= b.Time then
			local span = b.Time - a.Time
			local alpha = span > 0 and (t - a.Time) / span or 1
			alpha = (1 - math.cos(alpha * math.pi)) / 2 -- ease in-out
			return a.CFrames[jointName]:Lerp(b.CFrames[jointName], alpha)
		end
	end
	return last.CFrames[jointName]
end

---------------------------------------------------------------------------
-- Controller
---------------------------------------------------------------------------

function GuardianAnimations.new(model)
	local self = setmetatable({}, GuardianAnimations)
	self.Model = model
	self.Tracks = {}

	local ids = {
		Walk = model:GetAttribute("WalkAnimationId"),
		Attack = model:GetAttribute("AttackAnimationId"),
		Summon = model:GetAttribute("SummonAnimationId"),
	}
	local allSet = true
	for _, id in pairs(ids) do
		if type(id) ~= "string" or id == "" then
			allSet = false
		end
	end

	if allSet then
		-- Real Roblox animations through the Humanoid's Animator.
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local animator = humanoid:FindFirstChildOfClass("Animator") or Instance.new("Animator", humanoid)
		self.RobloxTracks = {}
		for name, id in pairs(ids) do
			if not string.find(id, "rbxassetid://", 1, true) then
				id = "rbxassetid://" .. id
			end
			local animation = Instance.new("Animation")
			animation.AnimationId = id
			local track = animator:LoadAnimation(animation)
			track.Looped = Data[name].Looped
			track.Priority = Enum.AnimationPriority[Data[name].Priority]
			self.RobloxTracks[name] = track
		end
		return self
	end

	-- Procedural: drive Motor6D.C0 from the keyframe data.
	self.Motors = {}
	for _, joint in ipairs(GuardianAnimations.Joints) do
		local part1 = model:FindFirstChild(joint.Part1, true)
		local motor = part1 and part1:FindFirstChild(joint.Name)
		if motor and motor:IsA("Motor6D") then
			self.Motors[joint.Name] = { Motor = motor, BaseC0 = motor.C0 }
		else
			warn("[GuardianAnimations] Missing Motor6D: " .. joint.Name)
		end
	end

	self.Connection = RunService.Heartbeat:Connect(function(dt)
		self:_step(dt)
	end)
	model.Destroying:Connect(function()
		self:Destroy()
	end)
	return self
end

-- Plays an animation. onMarker(markerName) is called for "Hit" / "Summon".
-- Returns the animation's length in seconds.
function GuardianAnimations:Play(name, fadeTime, onMarker)
	local anim = Data[name]
	assert(anim, "Unknown animation: " .. tostring(name))
	fadeTime = fadeTime or 0.15

	if self.RobloxTracks then
		local track = self.RobloxTracks[name]
		if self._markerConnections and self._markerConnections[name] then
			for _, c in ipairs(self._markerConnections[name]) do
				c:Disconnect()
			end
		end
		self._markerConnections = self._markerConnections or {}
		self._markerConnections[name] = {}
		if onMarker then
			for _, marker in ipairs(anim.Markers) do
				table.insert(
					self._markerConnections[name],
					track:GetMarkerReachedSignal(marker.Name):Connect(function()
						onMarker(marker.Name)
					end)
				)
			end
		end
		track:Play(fadeTime)
		return anim.Length
	end

	local existing = self.Tracks[name]
	self.Tracks[name] = {
		Anim = anim,
		Time = 0,
		Weight = existing and existing.Weight or 0,
		Target = 1,
		FadeTime = fadeTime,
		OnMarker = onMarker,
		NextMarker = 1,
	}
	return anim.Length
end

function GuardianAnimations:Stop(name, fadeTime)
	if self.RobloxTracks then
		self.RobloxTracks[name]:Stop(fadeTime or 0.2)
		return
	end
	local track = self.Tracks[name]
	if track then
		track.Target = 0
		track.FadeTime = fadeTime or 0.2
	end
end

function GuardianAnimations:IsPlaying(name)
	if self.RobloxTracks then
		return self.RobloxTracks[name].IsPlaying
	end
	local track = self.Tracks[name]
	return track ~= nil and track.Target > 0
end

function GuardianAnimations:GetLength(name)
	return Data[name].Length
end

function GuardianAnimations:_step(dt)
	-- Advance tracks, fire markers, handle fades.
	for name, track in pairs(self.Tracks) do
		local anim = track.Anim
		track.Time = track.Time + dt
		if anim.Looped then
			if track.Time >= anim.Length then
				track.Time = track.Time % anim.Length
				track.NextMarker = 1
			end
		elseif track.Time >= anim.Length then
			track.Time = anim.Length
			track.Target = 0
		end

		local marker = anim.Markers[track.NextMarker]
		while marker and track.Time >= marker.Time do
			if track.OnMarker then
				task.spawn(track.OnMarker, marker.Name)
			end
			track.NextMarker = track.NextMarker + 1
			marker = anim.Markers[track.NextMarker]
		end

		local step = track.FadeTime > 0 and dt / track.FadeTime or 1
		if track.Weight < track.Target then
			track.Weight = math.min(track.Target, track.Weight + step)
		elseif track.Weight > track.Target then
			track.Weight = math.max(track.Target, track.Weight - step)
		end
		if track.Target == 0 and track.Weight <= 0 then
			self.Tracks[name] = nil
		end
	end

	-- Layer tracks from lowest to highest priority.
	local ordered = {}
	for _, track in pairs(self.Tracks) do
		table.insert(ordered, track)
	end
	table.sort(ordered, function(a, b)
		return PRIORITY_ORDER[a.Anim.Priority] < PRIORITY_ORDER[b.Anim.Priority]
	end)

	for jointName, info in pairs(self.Motors) do
		local pose = CFrame.new()
		for _, track in ipairs(ordered) do
			if track.Anim.UsedJoints[jointName] and track.Weight > 0 then
				pose = pose:Lerp(sample(track.Anim, track.Time, jointName), track.Weight)
			end
		end
		info.Motor.C0 = info.BaseC0 * pose
	end
end

function GuardianAnimations:Destroy()
	if self.Connection then
		self.Connection:Disconnect()
		self.Connection = nil
	end
end

return GuardianAnimations
]=]
local BRAIN_SOURCE = [=[
-- GuardianBrain (Script inside the TreeGuardian model)
-- Simple boss AI: walks toward the nearest player, slams the ground when close, and
-- summons every so often. Settings live in the model's Attributes.
--
-- Hook your own effects in with the BindableEvents this creates:
--   model.Attacked.Event:Connect(function(impactPosition) ... end)
--   model.Summoned.Event:Connect(function() ... end) -- e.g. spawn minions here

local Players = game:GetService("Players")
local Debris = game:GetService("Debris")
local TweenService = game:GetService("TweenService")

local model = script.Parent
local humanoid = model:WaitForChild("Humanoid")
local root = model:WaitForChild("HumanoidRootPart")
local GuardianAnimations = require(model:WaitForChild("GuardianAnimations"))

local anims = GuardianAnimations.new(model)

local attackedEvent = Instance.new("BindableEvent")
attackedEvent.Name = "Attacked"
attackedEvent.Parent = model
local summonedEvent = Instance.new("BindableEvent")
summonedEvent.Name = "Summoned"
summonedEvent.Parent = model

local GLOW_COLOR = Color3.fromRGB(150, 255, 95)

local function setting(name, default)
	local value = model:GetAttribute(name)
	if value == nil then
		return default
	end
	return value
end

pcall(function()
	root:SetNetworkOwner(nil) -- the server moves the boss, so it never stutters
end)

local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
rayParams.FilterDescendantsInstances = { model }

local function groundBelow(position)
	local hit = workspace:Raycast(position + Vector3.new(0, 5, 0), Vector3.new(0, -60, 0), rayParams)
	if hit then
		return hit.Position
	end
	return Vector3.new(position.X, root.Position.Y - humanoid.HipHeight - root.Size.Y / 2, position.Z)
end

local function findTarget()
	local best, bestDistance = nil, setting("AggroRange", 90)
	for _, player in ipairs(Players:GetPlayers()) do
		local character = player.Character
		local hum = character and character:FindFirstChildOfClass("Humanoid")
		local hrp = character and character:FindFirstChild("HumanoidRootPart")
		if hum and hrp and hum.Health > 0 then
			local distance = (hrp.Position - root.Position).Magnitude
			if distance < bestDistance then
				best, bestDistance = hrp, distance
			end
		end
	end
	return best, bestDistance
end

local function face(position)
	local flat = Vector3.new(position.X, root.Position.Y, position.Z)
	if (flat - root.Position).Magnitude > 0.1 then
		root.CFrame = CFrame.lookAt(root.Position, flat)
	end
end

local function tweenThenDestroy(part, info, goal, lifetime)
	TweenService:Create(part, info, goal):Play()
	Debris:AddItem(part, lifetime)
end

local function effectPart(size, cframe, color, material)
	local p = Instance.new("Part")
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.Size = size
	p.CFrame = cframe
	p.Color = color
	p.Material = material
	p.Parent = workspace
	return p
end

---------------------------------------------------------------------------
-- Attack: ground slam shockwave
---------------------------------------------------------------------------
local function shockwave()
	local front = root.CFrame * CFrame.new(0, 0, -5)
	local center = groundBelow(front.Position)
	local radius = setting("ShockwaveRadius", 16)

	-- Damage and knock back everyone in range (once each).
	local overlap = OverlapParams.new()
	overlap.FilterType = Enum.RaycastFilterType.Exclude
	overlap.FilterDescendantsInstances = { model }
	local hitHumanoids = {}
	for _, part in ipairs(workspace:GetPartBoundsInRadius(center, radius, overlap)) do
		local hum = part.Parent and part.Parent:FindFirstChildOfClass("Humanoid")
		if hum and not hitHumanoids[hum] and hum.Health > 0 then
			hitHumanoids[hum] = true
			hum:TakeDamage(setting("AttackDamage", 30))
			local hrp = hum.Parent:FindFirstChild("HumanoidRootPart")
			if hrp then
				local away = hrp.Position - center
				away = Vector3.new(away.X, 0, away.Z)
				away = away.Magnitude > 0.1 and away.Unit or root.CFrame.LookVector
				hrp.AssemblyLinearVelocity = away * 60 + Vector3.new(0, 45, 0)
			end
		end
	end

	-- Glowing ring that expands and fades.
	local ring = effectPart(Vector3.new(0.4, 2, 2), CFrame.new(center) * CFrame.Angles(0, 0, math.rad(90)), GLOW_COLOR, Enum.Material.Neon)
	ring.Shape = Enum.PartType.Cylinder
	ring.Transparency = 0.2
	tweenThenDestroy(ring, TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		Size = Vector3.new(0.4, radius * 2, radius * 2),
		Transparency = 1,
	}, 0.6)

	-- Chunks of rock popping out of the ground.
	for i = 1, 8 do
		local angle = (i / 8) * math.pi * 2
		local offset = Vector3.new(math.cos(angle), 0, math.sin(angle)) * math.random(3, 7)
		local size = math.random(10, 18) / 10
		local rock = effectPart(Vector3.new(size, size, size), CFrame.new(center + offset) * CFrame.Angles(math.random(), math.random(), math.random()), Color3.fromRGB(78, 80, 90), Enum.Material.Slate)
		tweenThenDestroy(rock, TweenInfo.new(0.7, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			CFrame = rock.CFrame + Vector3.new(0, size * 1.5, 0),
			Transparency = 1,
		}, 0.8)
	end

	attackedEvent:Fire(center)
end

---------------------------------------------------------------------------
-- Summon: runes flare and glowing roots burst out of the ground around the boss
---------------------------------------------------------------------------
local function summonEffect()
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("BasePart") and d:GetAttribute("Glow") then
			local original = d.Color
			d.Color = Color3.new(1, 1, 1)
			TweenService:Create(d, TweenInfo.new(1.2), { Color = original }):Play()
		elseif d:IsA("PointLight") then
			local original = d.Brightness
			d.Brightness = original * 4
			TweenService:Create(d, TweenInfo.new(1.2), { Brightness = original }):Play()
		end
	end

	local center = groundBelow(root.Position)
	for i = 1, 6 do
		local angle = (i / 6) * math.pi * 2
		local spot = center + Vector3.new(math.cos(angle), 0, math.sin(angle)) * 10
		local height = math.random(5, 8)
		local startCFrame = CFrame.new(spot - Vector3.new(0, height / 2, 0)) * CFrame.Angles(0, angle, math.rad(math.random(-15, 15)))
		local pillar = effectPart(Vector3.new(1.2, height, 1.2), startCFrame, Color3.fromRGB(88, 56, 33), Enum.Material.Wood)
		local tip = effectPart(Vector3.new(0.6, 0.6, 0.6), startCFrame * CFrame.new(0, height / 2, 0), GLOW_COLOR, Enum.Material.Neon)
		local rise = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		TweenService:Create(pillar, rise, { CFrame = startCFrame + Vector3.new(0, height, 0) }):Play()
		TweenService:Create(tip, rise, { CFrame = startCFrame * CFrame.new(0, height / 2, 0) + Vector3.new(0, height, 0) }):Play()
		task.delay(1.6, function()
			local sink = TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			TweenService:Create(pillar, sink, { CFrame = startCFrame, Transparency = 1 }):Play()
			TweenService:Create(tip, sink, { CFrame = startCFrame, Transparency = 1 }):Play()
		end)
		Debris:AddItem(pillar, 2.3)
		Debris:AddItem(tip, 2.3)
	end

	summonedEvent:Fire()
end

---------------------------------------------------------------------------
-- Actions
---------------------------------------------------------------------------
local busy = false
local lastAttack = 0
local lastSummon = os.clock()

local function doAction(animName, onMarker)
	busy = true
	humanoid:MoveTo(root.Position)
	local length = anims:Play(animName, 0.15, onMarker)
	task.wait(length)
	busy = false
end

local function attack(target)
	face(target.Position)
	lastAttack = os.clock()
	doAction("Attack", function(marker)
		if marker == "Hit" then
			shockwave()
		end
	end)
end

local function summon()
	lastSummon = os.clock()
	doAction("Summon", function(marker)
		if marker == "Summon" then
			summonEffect()
		end
	end)
end

-- Walk animation follows actual movement.
task.spawn(function()
	while humanoid.Parent and humanoid.Health > 0 do
		local velocity = root.AssemblyLinearVelocity
		local moving = Vector3.new(velocity.X, 0, velocity.Z).Magnitude > 1 and not busy
		if moving and not anims:IsPlaying("Walk") then
			anims:Play("Walk", 0.2)
		elseif not moving and anims:IsPlaying("Walk") then
			anims:Stop("Walk", 0.25)
		end
		task.wait(0.1)
	end
end)

humanoid.Died:Connect(function()
	anims:Destroy()
	Debris:AddItem(model, 8)
end)

-- Main loop.
while humanoid.Parent and humanoid.Health > 0 do
	local target, distance = findTarget()
	if target and not busy then
		local attackRange = setting("AttackRange", 13)
		if os.clock() - lastSummon >= setting("SummonCooldown", 14) then
			face(target.Position)
			summon()
		elseif distance <= attackRange and os.clock() - lastAttack >= setting("AttackCooldown", 3) then
			attack(target)
		elseif distance > attackRange * 0.7 then
			humanoid:MoveTo(target.Position)
		else
			humanoid:MoveTo(root.Position)
			face(target.Position)
		end
	elseif not target and not busy then
		humanoid:MoveTo(root.Position)
	end
	task.wait(0.2)
end
]=]

local COLORS = {
	Wood = Color3.fromRGB(124, 80, 46),
	WoodDark = Color3.fromRGB(88, 56, 33),
	WoodLight = Color3.fromRGB(152, 104, 62),
	Stone = Color3.fromRGB(78, 80, 90),
	StoneDark = Color3.fromRGB(52, 54, 62),
	Leaves = Color3.fromRGB(62, 145, 48),
	LeavesDark = Color3.fromRGB(42, 112, 38),
	LeavesLight = Color3.fromRGB(98, 180, 64),
	Glow = Color3.fromRGB(150, 255, 95),
	Vines = Color3.fromRGB(48, 92, 38),
	Mouth = Color3.fromRGB(30, 20, 14),
}

local M = Enum.Material
local rad = math.rad

local model = Instance.new("Model")
model.Name = "TreeGuardian"
model.Parent = workspace -- parented early so require() below works; nothing moves in edit mode

local function styleParts(p, color, material)
	p.Color = color
	p.Material = material
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
end

-- Main body part (one per joint), positioned in world space with feet on y = 0.
local parts = {}
local function body(name, size, position, color, material, canCollide)
	local p = Instance.new("Part")
	p.Name = name
	p.Size = size
	p.CFrame = CFrame.new(position)
	styleParts(p, color, material)
	p.CanCollide = canCollide
	p.Parent = model
	parts[name] = p
	return p
end

-- Decoration welded onto a body part. offset is relative to that part's center.
local function deco(parent, name, size, offset, color, material)
	local p = Instance.new("Part")
	p.Name = name
	p.Size = size
	p.CFrame = parent.CFrame * offset
	styleParts(p, color, material)
	p.CanCollide = false
	p.CanTouch = false
	p.Massless = true
	local weld = Instance.new("Weld")
	weld.Part0 = parent
	weld.Part1 = p
	weld.C0 = offset
	weld.Parent = p
	p.Parent = parent
	return p
end

local function glow(parent, name, size, offset)
	local p = deco(parent, name, size, offset, COLORS.Glow, M.Neon)
	p:SetAttribute("Glow", true)
	return p
end

local function at(x, y, z, rx, ry, rz)
	return CFrame.new(x, y, z) * CFrame.Angles(rad(rx or 0), rad(ry or 0), rad(rz or 0))
end

local function light(parent, range, brightness)
	local l = Instance.new("PointLight")
	l.Color = COLORS.Glow
	l.Range = range
	l.Brightness = brightness
	l.Parent = parent
	return l
end

